  assigns={}; newly_frozen=[]
  for r,c in unresolved:
   colors=set()
   for dr,dc in off:
    rr,cc=r+dr,c+dc
    if 0<=rr<inp.shape[0] and 0<=cc<inp.shape[1] and out[rr,cc] in seeds:
     colors.add(int(out[rr,cc]))
   if len(colors)==1:assigns[(r,c)]=next(iter(colors))
   elif len(colors)>1:newly_frozen.append((r,c))
  if not assigns and not newly_frozen:break
  for (r,c),v in assigns.items():out[r,c]=v
  for p in list(assigns)+newly_frozen:unresolved.discard(p)
  # if tie, it stays net and is frozen, cannot propagate
